<?php
declare(strict_types=1);
session_start();
require_once __DIR__.'/../lib/storage.php';
require_once __DIR__.'/../lib/testimonials.php';
if(empty($_SESSION['ferrn_admin'])){header('Location:/admin/');exit;}
function t_csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['csrf'];}
function t_valid():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid request');}}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  t_valid();$action=(string)($_POST['action']??'');$items=ferrn_testimonials();
  if($action==='save'){
    $id=trim((string)($_POST['id']??''));$name=trim((string)($_POST['name']??''));$role=trim((string)($_POST['role']??''));$image=trim((string)($_POST['image']??''));$audio=trim((string)($_POST['audio']??''));$sort=(int)($_POST['sort']??999);
    if($name===''||!filter_var($image,FILTER_VALIDATE_URL)||!filter_var($audio,FILTER_VALIDATE_URL)){$error='Name, valid image URL and valid audio URL are required.';}
    else{
      if($id==='')$id=ferrn_slugify($name.'-'.bin2hex(random_bytes(2)));
      $entry=['id'=>$id,'name'=>$name,'role'=>$role,'image'=>$image,'audio'=>$audio,'active'=>!empty($_POST['active']),'sort'=>$sort];
      $found=false;foreach($items as &$t){if(($t['id']??'')===$id){$t=$entry;$found=true;break;}}unset($t);if(!$found)$items[]=$entry;
      ferrn_save_testimonials($items);header('Location:/admin/testimonials.php');exit;
    }
  }
  if($action==='delete'){$id=(string)($_POST['id']??'');ferrn_save_testimonials(array_values(array_filter($items,fn($t)=>($t['id']??'')!==$id)));header('Location:/admin/testimonials.php');exit;}
}
$items=ferrn_testimonials();$edit=null;if(!empty($_GET['edit']))foreach($items as $t)if(($t['id']??'')===$_GET['edit']){$edit=$t;break;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Testimonials — Ferrn Admin</title><link rel="icon" href="/assets/ferrn-mark.svg"><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap" rel="stylesheet"><style>:root{--o:#ff4100}*{box-sizing:border-box}body{margin:0;background:#090909;color:#f5f5f2;font-family:Poppins,Arial}.wrap{width:min(1280px,100%);margin:auto;padding:32px clamp(18px,4vw,58px)}.nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:28px}.nav a{color:#aaa;text-decoration:none;padding:9px 12px;border:1px solid #2b2b2b;border-radius:99px;font-size:12px}.nav a.active,.nav a:hover{background:#171717;color:#fff}.head{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:22px}.head h1{font-size:40px;margin:0}.muted{color:#777;font-size:12px}.grid{display:grid;grid-template-columns:390px 1fr;gap:18px}.panel{background:#111;border:1px solid #242424;border-radius:18px;padding:20px}.panel h2{margin:0 0 16px}.field{display:grid;gap:6px;margin-top:12px}.field label{font-size:10px;color:#888}.field input{width:100%;background:#080808;border:1px solid #2a2a2a;border-radius:10px;padding:12px;color:#fff}.check{display:flex;gap:8px;align-items:center;font-size:12px;color:#aaa;margin-top:14px}.btn{border:0;border-radius:99px;background:var(--o);color:#fff;padding:11px 15px;font-weight:600;font-size:11px;cursor:pointer;text-decoration:none;display:inline-flex}.btn.secondary{background:#1a1a1a;border:1px solid #303030}.btn.danger{background:#36130c;color:#ff9d84}.actions{display:flex;gap:7px;flex-wrap:wrap}.list{display:grid;gap:10px}.item{display:grid;grid-template-columns:70px 1fr auto;gap:14px;align-items:center;padding:12px;border:1px solid #242424;border-radius:14px}.item img{width:70px;height:70px;object-fit:cover;border-radius:12px}.item strong{display:block}.item span{display:block;color:#777;font-size:11px;margin-top:4px}.badge{display:inline-block!important;width:max-content;padding:4px 7px;border:1px solid #303030;border-radius:99px;margin-top:7px!important}.error{padding:10px;background:#35130c;color:#ffa088;border-radius:10px;margin-bottom:12px}@media(max-width:900px){.grid{grid-template-columns:1fr}.head{display:block}.item{grid-template-columns:60px 1fr}.item img{width:60px;height:60px}.item .actions{grid-column:1/-1}}</style></head><body><main class="wrap"><nav class="nav"><a href="/admin/">Dashboard</a><a href="/admin/?tab=leads">Leads</a><a href="/admin/?tab=projects">Projects</a><a href="/admin/?tab=posts">Posts</a><a class="active" href="/admin/testimonials.php">Testimonials</a></nav><div class="head"><div><div class="muted">FERRN DIGITAL AGENCY</div><h1>Testimonials</h1></div><span class="muted"><?=count($items)?> testimonials</span></div><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="grid"><section class="panel"><h2><?=$edit?'Edit testimonial':'Add testimonial'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=t_csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=htmlspecialchars($edit['id']??'')?>"><div class="field"><label>Name</label><input name="name" value="<?=htmlspecialchars($edit['name']??'')?>" required></div><div class="field"><label>Role / company</label><input name="role" value="<?=htmlspecialchars($edit['role']??'')?>"></div><div class="field"><label>Image URL</label><input name="image" type="url" value="<?=htmlspecialchars($edit['image']??'')?>" placeholder="https://..." required></div><div class="field"><label>Audio URL</label><input name="audio" type="url" value="<?=htmlspecialchars($edit['audio']??'')?>" placeholder="https://...mp3" required></div><div class="field"><label>Order</label><input name="sort" type="number" value="<?=htmlspecialchars((string)($edit['sort']??(count($items)+1)))?>"></div><label class="check"><input type="checkbox" name="active" value="1" <?=!isset($edit['active'])||!empty($edit['active'])?'checked':''?>> Show on website</label><div class="actions" style="margin-top:18px"><button class="btn">Save testimonial</button><?php if($edit):?><a class="btn secondary" href="/admin/testimonials.php">Cancel</a><?php endif;?></div></form></section><section class="panel"><h2>Current testimonials</h2><div class="list"><?php foreach($items as $t):?><article class="item"><img src="<?=htmlspecialchars($t['image']??'')?>" alt=""><div><strong><?=htmlspecialchars($t['name']??'')?></strong><span><?=htmlspecialchars($t['role']??'')?></span><span class="badge"><?=!empty($t['active'])?'Visible':'Hidden'?> · Order <?=htmlspecialchars((string)($t['sort']??''))?></span></div><div class="actions"><a class="btn secondary" href="?edit=<?=urlencode((string)($t['id']??''))?>">Edit</a><form method="post" onsubmit="return confirm('Remove this testimonial?')"><input type="hidden" name="csrf" value="<?=t_csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=htmlspecialchars($t['id']??'')?>"><button class="btn danger">Remove</button></form></div></article><?php endforeach;?></div></section></div></main></body></html>
